0,"Create a Go program that implements a function which accepts a URL as an argument and returns the HTTP status code of the requested resource. The function should use the `net/http` package to make an HTTP GET request to the specified URL, and then extract and return the status code from the response. Additionally, include functionality to measure the time taken for the request and display it in milliseconds. Furthermore, implement error handling to catch any issues with making the request or parsing the response, logging these errors appropriately.",807,,"['```go
package main

import (
	""fmt""
	""io/ioutil""
	""net/http""
	""time""
)

func GetStatusCode(url string) (int, error) {
	start := time.Now()
	resp, err := http.Get(url)
	if err != nil {
		return 0, fmt.Errorf(""error making request: %w"", err)
	}
	defer resp.Body.Close()

