def enhanced_sort_and_extract(file_path, expected_sequence_number=None):
    try:
        with open(file_path, 'r') as f:
            lines = f.readlines()

        sorted_lines = sorted(lines)

        last_line = sorted_lines[-1].strip()
        if not last_line.isdigit():
            raise ValueError(""No valid sequence number found in the last line."")

        extracted_sequence_number = int(last_line)

        if expected_sequence_number is not None and extracted_sequence_number != expected_sequence_number:
            raise ValueError(f""Expected sequence number {expected_sequence_number} not found."")

        return sorted_lines, extracted_sequence_number == expected_sequence_number
