0,"Develop a Go program featuring a function that takes a URL as input and outputs the HTTP status code of the accessed resource. This function should leverage the `net/http` package to execute an HTTP GET request to the given URL, subsequently extracting and returning the status code from the response. Moreover, incorporate functionality to measure the request duration in milliseconds and present it. Enhance error management by addressing any potential issues in making or parsing the response, ensuring appropriate logging of these errors.",807,,"['```go
package main

import (
	""fmt""
	""io/ioutil""
	""net/http""
	""net/url""
	""time""
)

func GetStatusAndDuration(url string) (int, int64) {
	duration := int64
	resp, err := http.Get(url)
	if err != nil {
		fmt.Println(""Error: "", err)
		return 0, 0
	}
	defer resp.Body.Close()
	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		fmt.Println(""Error reading response body: "", err)
		return resp.StatusCode, 0
	}

	duration = time.Now().Sub(resp.Time).Milliseconds()
	return resp.StatusCode, duration
}

func main() {
	inputURL := ""https://example.com""
	statusCode, duration := GetStatusAndDuration(inputURL)
	fmt.Printf(""The status code of the accessed resource is: %d\n"", statusCode)
	fmt.Printf(""The request duration in milliseconds is: %d\n"", duration)
}
