import json
import random
import time
from collections import defaultdict

class GraphDatabase:
    def __init__(self, vertices=None, edges=None):
        self.vertices = vertices if vertices else []
        self.edges = edges if edges else []

    def to_json(self):
        data = {'vertices': [v.to_json() for v in self.vertices], 'edges': [e.to_json() for e in self.edges]}
        return json.dumps(data)

    class Vertex:
        def __init__(self, id, properties=None):
            self.id = id
            self.properties = properties or {}

        def to_json(self):
            return json.dumps({'id': self.id, 'properties': self.properties})

    class Edge:
        def __init__(self, src, dest, properties=None):
            self.src = src
            self.dest = dest
            self.properties = properties or {}

        def to_json(self):
            return json.dumps({'source': self.src.id, 'destination': self.dest.id, 'properties': self.properties})

class RandomGraphFactory:
    factories_registry = {}

    @classmethod
    def register_factory(cls, id):
        def decorator(func):
            cls.factories_registry[id] = func
            return func

        return decorator

    @classmethod
    def create_graph(cls, id, num_vertices, num_edges):
        if id not in cls.factories_registry:
            raise ValueError(f""Factory with ID '{id}' not found."")

        graph = cls.factories_registry[id](num_vertices, num_edges)
        return graph

@RandomGraphFactory.register_factory('random')
def generate_random_graph(num_vertices, num_edges):
    graph_db = GraphDatabase()
    vertex_props = {'type': 'node', 'value': random.randint(1, 100)}
    edge_props = {'weight': random.uniform(0, 1), 'direction': random.choice(['directed', 'undirected'])}

    vertices = [RandomGraphFactory.Vertex(id, vertex_props) for _ in range(num_vertices)]
    edges = [(vertices[src], vertices[dest]) for src, dest in zip(random.sample(range(len(vertices)), num_edges), random.combinations(range(len(vertices)), r=2))]

    # Generate edges based on edge probability and properties
    edge_probability = 0.5
    for src, dest in edges:
        roll = random.random()
        if roll < edge_probability:
            graph_db.edges.append(RandomGraphFactory.Edge(src, dest, edge_props))

    return graph_db
```

