package dbg

import (
    ""database/sql""
    ""github.com/google/uuid""
)

type DatabaseRandomValueGenerator struct {
    randSource *rand.Source
}

func NewDatabaseRandomValueGenerator(src *rand.Source) *DatabaseRandomValueGenerator {
    return &DatabaseRandomValueGenerator{
        randSource: src,
    }
}

// GenerateRandomUUID returns a new UUID
func (g *DatabaseRandomValueGenerator) GenerateRandomUUID() uuid.UUID {
    _, err := g.generateUUID(""id"")
    if err != nil {
        panic(err)
    }
    return uuid.UUID{}
}

// GenerateRandomFloat generates a float number within the given range
func (g *DatabaseRandomValueGenerator) GenerateRandomFloat(min, max float64) float64 {
    sequenceNumber := g.generateSequenceNumber(""sequence_number"")
    return min + sequenceNumber*(max-min)/10
}

// GenerateRandomInteger generates an integer number within the given range
func (g *DatabaseRandomValueGenerator) GenerateRandomInteger(min, max int64) int64 {
    sequenceNumber := g.generateSequenceNumber(""sequence_number"")
    return min + sequenceNumber*(max-min)/10
}

// generateUUID generates a new UUID and stores it in the database
func (g *DatabaseRandomValueGenerator) generateUUID(columnName string) (uuid.UUID, error) {
    db, err := sql.Open(""sqlite3"", ""./data.db"")
    if err != nil {
        return uuid.UUID{}, err
    }
    defer db.Close()

    id := uuid.New()
    _, err = db.Exec(""REPLACE INTO data (id) VALUES (?)"", id)
    if err != nil {
        return uuid.UUID{}, err
    }

    row := db.QueryRow(""SELECT id FROM data ORDER BY ? DESC LIMIT 1"", columnName)
    var lastID uuid.UUID
    err = row.Scan(&lastID)
    if err != nil {
        return uuid.UUID{}, err
    }

    return lastID, nil
}

// generateSequenceNumber generates a sequence number based on the sorted data
func (g *DatabaseRandomValueGenerator) generateSequenceNumber(columnName string) int64 {
    db, err := sql.Open(""sqlite3"", ""./data.db"")
    if err != nil {
        panic(err)
    }
    defer db.Close()

    var count int64
    row := db.QueryRow(""SELECT COUNT(*) FROM data ORDER BY ? DESC"", columnName)
    err = row.Scan(&count)
