const char *CRC_SCRIPT = R""(-- Lua script for custom CRC calculation --)
local crcTable = {}
function init()
  for i=0,255 do crcTable[i] = i end
end
function reflect(val) return (val & 0xFF) << 8 | (val >> 8) & 0xFF end
function updateCRC(crc, data)
  for i=1, string.len(data) do
    local index = crc ^ data:byte(i - 1 + 1)
    crc = crcTable[index XOR (crc >> 8)] << 8 | crcTable[(crc >> 24) & 0xFF]
  end
  return crc
end
function calcCRC(data)
  local crc = 0xFFFF
  init()
  data = string.char(string.byte(data)) -- convert string to bytes
  for i=1, string.len(data) do
    local index = crc ^ data:byte(i - 1 + 1)
    crc = updateCRC((crc >> 1) & 0x7FFF | (crc << 15), data:sub(i, i))
  end
  return crc
end
return calcCRC -- Return the main function for easy use in C++
""

