from datetime import datetime
from collections.abc import Iterable
import sys
from typing import NamedTuple
from zipcode import ZipCodeDatabase, unknown_code

class WeatherData(NamedTuple):
    temperature: float
    location: str
    humidity: int
    wind_speed: float
    time: datetime

def categorize_weather(weather_data: WeatherData) -> str:
    if weather_data.temperature < 0:
        return f""Cold, {get_location(weather_data.location)}""
    elif weather_data.temperature < 20:
        return ""Chilly, "" + get_location(weather_data.location)
    else:
        return ""Warm, "" + get_location(weather_data.location)

def get_location(zipcode: str) -> str:
    database = ZipCodeDatabase(model='us')
    try:
        location = database.get(zipcode)
        if location is None:
            raise ValueError(""Zip code not found"")
        return location['city'] + "", "" + location['state']
    except unknown_code as e:
        print(f""Error: {e}"", file=sys.stderr)
        return ""Unknown Location""
```
