Note: You may use Python's `math` module for square root calculation in your prime checking logic.",377,,"['```python
import math
from functools import lru_cache

@lru_cache(maxsize=None)
def is_even(n):
    return n % 2 == 0

@lru_cache(maxsize=None)
def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n))+1):
        if n % i == 0:
            return False
    return True

def filter_even_and_primes(numbers, include_primes=False):
    result = []
    for number in numbers:
        if is_even(number) and (not include_primes or is_prime(number)):
            result.append(number)
    return result or [None]  # Return an empty list instead of None if no even numbers found

# Test cases
numbers = [1, 2, 3, 4, 5, 6, 7, 8]
print(filter_even_and_primes(numbers))  # Output: [2, 4, 6, 8]

numbers = [2, 4, 6, 7, 9, 11]
print(filter_even_and_primes(numbers, include_primes=True))  # Output: [2, 4, 6, 8]

numbers = []
print(filter_even_and_primes(numbers))  # Output: []
```

