import os
import re
from typing import List, Tuple, Optional

def enhanced_sort_and_extract(file_path: str, expected_sequence_number: Optional[int] = None) -> Tuple[List[str], bool]:
    try:
        with open(file_path, 'r') as file:
            lines = [line.strip() for line in sorted(file)]
    except FileNotFoundError:
        raise FileNotFoundError(f""The specified file '{file_path}' doesn't exist."")

    sequence_pattern = r'^Sequence Number: (\d+)$'
    last_line = lines[-1]

    if not re.match(sequence_pattern, last_line):
        raise ValueError(""No sequence number found in the last line or invalid sorting lines."")

    sequence_number = int(re.search(sequence_pattern, last_line).group(1))

    if expected_sequence_number is not None:
        if sequence_number != expected_sequence_number:
            return lines, False
        else:
            return lines, True
    else:
        return lines, True
