import random
import os

class Character:
    def __init__(self, name):
        self.name = name
        self.attack_list = []
        self.current_cooldown = 0
        self.num_attacks_available = 0

    def load_resource_bundle(self, file_path, num_items):
        with open(file_path, 'r') as f:
            for line in f:
                attack = line.strip()
                self.attack_list.append(attack)
                if len(self.attack_list) >= num_items:
                    break

    def select_attack(self):
        if not self.num_attacks_available or self.current_cooldown > 0:
            return None
        available_attacks = [attack for attack in self.attack_list if attack not in self.attacks_used]
        selected_attack = random.choice(available_attacks)
        self.attacks_used.append(selected_attack)
        self.num_attacks_available -= 1
        return selected_attack

class GameEnvironment:
    def __init__(self):
        self.resource_bundles = {}

    def load_resource_bundle(self, file_path):
        # Load resource bundles based on game state
        self.resource_bundles[file_path] = []
        with open(file_path, 'r') as f:
            for line in f:
                self.resource_bundles[file_path].append(line.strip())

    def get_resource_bundle(self, environment_state):
        # Return a specific resource bundle based on current game state or level
        return self.resource_bundles[environment_state]

class GameEnvironmentManager:
    def __init__(self):
        self.environments = {""castle_environment"": {""resource_bundles"": [""castle_attacks.txt""], ""level_completion_bonus"": ""sword""},
                             ""cave_environment"": {""resource_bundles"": [""cave_attacks.txt""], ""level_completion_bonus"": ""potion""}}

    def get_environment(self, player_state):
