import random
import sys

class RecordManager:
    def __init__(self, num_structures):
        self.records = [self._initialize_record() for _ in range(num_structures)]

    def _initialize_record(self):
        ue_identification = [random.randint(10 ** (i - 2), 10 ** i) for i in range(2, 19)]
        tai = random.choice(range(100000, 200000))
        gpsranging_result_flag = random.randint(0, 255)

        return {
            'ue_identification': ue_identification,
            'tai': tai,
            'gpsranging_result_flag': gpsranging_result_flag
        }

    def generate_nfapi_gpsranging_pdu_t(self):
        for record in self.records:
            yield {
                'header': {'version': 1, 'length': len(record)},
                **record
            }

    def generateRandomArraySizes(self, minSize=2, maxSize=18):
        return random.randint(minSize, maxSize)

    def allocateDynamicArrays(self, arrayName, size):
        getattr(self, f'_{arrayName}s').append([None] * size)

    def populateDynamicArrays(self):
        for array in ['ue_identification', 'tai']:
            getattr(self, f'_{array}_values')[::] = [
                self._generate_unique_identifier() for _ in range(len(getattr(self, array)))
            ]

    def _releaseDynamicMemory(self):
        for array in ['ue_identification', 'tai']:
            del getattr(self, f'_{array}_values')[::]

    def _generate_unique_identifier(self):
        return random.randint(10 ** (len(self._unique_ids) - 2), 10 ** len(self._unique_ids))

    def _unique_ids(self):
        self._unique_ids = set() if not hasattr(self, '_unique_ids') else getattr(self, '_unique_ids')
        while True:
            yield random.randint(10 ** (len(self._unique_ids) - 2), 10 ** len(self._unique_ids))
            self._unique_ids.add(self._generate_unique_identifier())

    def deallocateMemory(self):
        for record in self.records:
            record['ue_identification'] = []
            record['tai'] = None
            record['gpsranging_result_flag'] = None
        self._unique_ids = set()

    def validateInput(self, input, maxLength=19):
        if len(input) > maxLength:
            raise ValueError(f""Input string length exceeds the maximum allowed of {maxLength} characters."")

def main():
