def serializeStructs(data, filename):
    with open(filename, 'wb') as f:
        for d in data:
            packed_struct = struct.pack('>IIB', d['tag'], d['rnti'], d['crcflag'])
            f.write(packed_struct)

def deserializeStructs(filename):
    with open(filename, 'rb') as f:
        while True:
            packed_struct = f.read(12)
            if not packed_struct:
