def serialize(obj):
    return json.dumps(obj).encode()

def deserialize(data):
    return json.loads(data.decode())

def encrypt(data):
    cipher = AES.new(key, AES.MODE_CBC, iv)
    return iv + cipher.encrypt(data)

def decrypt(data):
    if len(data) < AES.block_size:
