def verify_integrity(filepath, hashed_data):
    sha256 = hashlib.sha256()
    with open(filepath, 'rb') as file:
        while True:
            data = file.read(64 * 1024)
            if not data:
                break
            sha256.update(data)
    return hashed_data == sha256.digest()

