import sys
import logging
import time
from collections import Counter

def validate_input(input_str):
    valid_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789')
    for char in input_str:
        if char not in valid_chars:
            raise ValueError(f'Invalid character detected: {char}')

def word_count(input_str):
    return len(input_str.split())

def frequency_analysis(input_str):
    freq = Counter(input_str)
    return dict(freq)

def progress_indicator(processed_chars, total_chars):
    completed_percentage = (processed_chars / total_chars) * 100
    processed_percentage = int(completed_percentage + 0.5)
    filled_bars = '#' * processed_percentage
    empty_bars = '#' * (100 - processed_percentage)
    return f'\rProgress: {filled_bars}{empty_bars} {processed_percentage}%', processed_chars + 1

def main(input_str):
    try:
        validate_input(input_str)
        if len(input_str) > 1000:
            raise ValueError('Input string exceeds the maximum size limit of 1000 characters.')

        total_chars = len(input_str)
        processed_chars, words_count = 0, 0
        freq_analysis = {}

        logging.basicConfig(filename='error_log.txt', level=logging.ERROR)

        for char in input_str:
            processed_chars += 1
            sys.stdout.write(progress_indicator(processed_chars, total_chars))
            sys.stdout.flush()

            if char.isalpha():
                words_count += (char == ' ') and len(freq_analysis) > 0 or 1
            elif char in freq_analysis:
                freq_analysis[char] += 1
            else:
                freq_analysis[char] = 1

        sys.stdout.write('\n')
        logging.info(f'Word count: {words_count}')
        logging.info(f'Frequency analysis: {freq_analysis}')
    except Exception as e:
        logging.error(f'Error occurred during character frequency calculation: {e}')
        raise

if __name__ == '__main__':
    main('Hello, World!1234567890 Hello Again 1234567890')
