 if not set, configure it with a default path. Extract a specific PDF from the compressed root directory and save it in an archive folder.",276,,"['```python
import os
import tarfile
import shutil
from pathlib import Path

def get_root_dir():
    return ""C:/Compressed_Files"" if not os.path.exists(""Compressed_Files"") else ""Compressed_Files""

def decompress_tar(src, dest):
    with tarfile.open(src) as tar:
        tar.extractall(dest=dest)

def extract_pdf(root_dir, archive_folder):
    for file in root_dir.glob(""*.zip""):
        with tarfile.open(file, ""r:zip"") as tar:
            tar.extractall(path=archive_folder)
            pdf_files = [Path(f""{archive_folder}/{os.path.basename(file)}"").with_suffix("".pdf"") for f in archive_folder.glob(""*"")]
            if len(pdf_files) > 0:
                return pdf_files[0]
    return None

def main():
    root_dir = Path(get_root_dir())
    archive_folder = Path(""Archive"")

    if not archive_folder.exists():
        os.makedirs(archive_folder)

    for file in root_dir.glob(""*.tar""):
        decompress_tar(file, root_dir)
        pdf_path = extract_pdf(root_dir, archive_folder)
        if pdf_path:
            shutil.copy(pdf_path, ""PDFs"")

if __name__ == ""__main__"":
    main()
