    payload = {'exp': datetime.utcnow() + timedelta(seconds=expiration_time)}
    return jwt.encode(payload, secret_key, algorithm='HS256')

def verify_jwt(secret_key, token):
    try:
        decoded = jwt.decode(token, secret_key, algorithms=['HS256'])
    except Exception as e:
        raise ValueError('Invalid or expired JWT') from e

    if datetime.fromtimestamp(decoded['exp']) < datetime.utcnow():
        raise ValueError('Invalid or expired JWT')

def main(file_path, client_id, client_secret, jwt_secret_key, token_expiration):
