import math
import time
from decimal import Decimal

def calculate_stats(numbers, threshold=None):
    try:
        start_time = time.time()
        valid_numbers = [float(n) for n in numbers if type(n) is float]
        if not all([isinstance(n, float) for n in valid_numbers]):
            raise ValueError(""All elements in the list must be floating-point numbers."")

        max_value = max(valid_numbers)
        min_value = min(valid_numbers)

        if threshold:
            valid_numbers = [n for n in valid_numbers if n <= threshold]

        geometric_mean = Decimal(math.pow(math.fsum([abs(x) for x in valid_numbers]), 0).sqrt()).quantize(Decimal('0.001'))

        elapsed_time = time.time() - start_time

        return {'geometric_mean': geometric_mean, 'maximum': max_value, 'minimum': min_value, 'execution_time': elapsed_time}
    except ValueError as e:
        print(f""Error: {e}"")
