0,"Create a script to check for decompressed files in the root directory. If a compressed file is found, decompress it, remove the compressed file, and extract a specific PDF from the decompressed directory. Save the extracted PDF in an archive folder. Set a default path if none is provided.",276,,"['```python
import os
import zipfile
import shutil
import tarfile
import archivestore

def extract_and_get_pdf(path):
    archive_folder = 'archive' if not os.path.exists('archive') else os.path.abspath('archive')
    os.makedirs(archive_folder, exist_ok=True)

    extracted_folder = ''
    file_extension = None

    for root, dirs, files in os.walk(path):
        for file in files:
            if zipfile.is_zipfile(os.path.join(root, file)) or tarfile.is_tarfile(os.path.join(root, file)):
                file_extension = os.path.splitext(file)[1]
                extracted_folder = os.path.join(archive_folder, f'{os.path.basename(path)}_{os.path.splitext(file)[0]}')
                if not os.path.exists(extracted_folder):
                    os.makedirs(extracted_folder)
                if file_extension == '.zip':
                    with zipfile.ZipFile(os.path.join(root, file), 'r') as z:
                        z.extractall(extracted_folder)
                elif file_extension == '.tar.gz' or file_extension == '.tar':
                    with tarfile.open(os.path.join(root, file), 'r:*') as tar:
                        tar.extractall(path=extracted_folder)

    if extracted_folder and os.path.exists(extracted_folder):
        pdf_files = [f for f in os.listdir(extracted_folder) if f.endswith('.pdf')]
        if pdf_files:
            shutil.copyfile(os.path.join(extracted_folder, pdf_files[0]), os.path.join(archive_folder, pdf_files[0]))
            print(f'PDF file {pdf_files[0]} has been saved in archive folder.')
        else:
            print('No PDF file found in the decompressed directory.')
    else:
        print('No compressed files found in the given path.')

if __name__ == ""__main__"":
    root_directory = '.' if not os.path.exists('archive') else os.path.abspath('archive')
    extract_and_get_pdf(root_directory)
