256,"Design and implement a Python script that automates the process of collecting data from various online platforms by leveraging web scraping techniques. The script should be capable of handling both static and dynamic web pages, supporting multiple output formats like CSV, JSON, XML, and TSV. It should incorporate features for managing concurrent requests, handling CAPTCHA challenges using OCR or other methods, implementing rate limiting to prevent IP blocking, offering customizable data filtering and cleaning based on regular expressions or conditions, extending functionality to scrape data from paginated pages on dynamic sites, utilizing a configurable proxy pool to overcome geolocation restrictions and bypass anti-scraping mechanisms, enhancing logging capabilities with colored output, timestamps, and file-based logging based on severity levels. The script should also include an interface for setting up scraping tasks through a command-line tool or configuration file. Additionally, the script should automatically update the WebDriver version based on supported browser versions and provide an option for users to specify preferred output formats.",676,,"['```python
import os
import re
import time
import requests
from bs4 import BeautifulSoup
from selenium import webdriver
from selenium.webdriver.chrome.options import Options
import csv
import json
import xml.etree.ElementTree as ET
import logging
from logging.handlers import RotatingFileHandler

class Scraper:
    def __init__(self, config):
        self.config = config
        self.output_format = config['output_format']
        self.proxies = config['proxies'] if 'proxies' in config else None
        self.rate_limit = int(config['rate_limit']) if 'rate_limit' in config else 60
        self.regex_filter = re.compile(config['regex_filter']) if 'regex_filter' in config else None
        self.condition_filter = lambda x: True
        if 'condition_filter' in config:
            self.condition_filter = eval(config['condition_filter'])
        self.browser = webdriver.Chrome()
        self.log_handler = RotatingFileHandler('scraper.log', maxBytes=10e6, backupCount=5)
        self.log_handler.setLevel(logging.DEBUG)
        logging.basicConfig(handlers=[self.log_handler], level=logging.INFO)

    def scrape(self, url):
        start = time.time()
        data = []
        try:
            if self.proxies:
                proxy = random.choice(self.proxies)
                proxy_url = f'http://{proxy[""ip""]}:{proxy[""port""]}'
                options = Options()
                options.add_argument(f'--proxy={proxy_url}')
                self.browser = webdriver.Chrome(options=options)
            self.browser.get(url)
            soup = BeautifulSoup(self.browser.page_source, 'html.parser')
            for element in soup.find_all():
                if self.regex_filter and re.match(self.regex_filter, str(element)):
                    continue
                if not self.condition_filter(element):
                    continue
                data.append(self._format_data(element))
            logging.info(f'Scraped {len(data)} items from {url} in {time.time() - start:.2f} seconds')
        except Exception as e:
            logging.error(f'Error while scraping {url}: {e}')
        self._save_output(data)
        if self.proxies:
            self.browser.quit()

    def _format_data(self, element):
        if self.output_format == 'csv':
            return [str(element)]
        elif self.output_format == 'json':
            return {str(element)}
        elif self.output_format == 'xml':
            root = ET.Element('item')
            root.text = str(element)
            return ET.tostring(root, encoding='unicode', method='html')
        elif self.output_format == 'tsv':
            return [str(element)]
        else:
            raise ValueError(f'Unsupported output format: {self.output_format}')

    def _save_output(self, data):
        if not os.path.exists('output'):
            os.makedirs('output')
        filename = f""output/{time.strftime('%Y-%m-%d_%H-%M-%S')}_{self.output_format}.{self.output_format}""
        with open(filename, 'w', newline='') as file:
            if self.output_format == 'csv':
                writer = csv.writer(file)
                for row in data:
                    writer.writerow(row)
            elif self.output_format == 'json':
                json.dump(data, file)
            elif self.output_format == 'xml':
                root = ET.Element('root')
                for item in data:
                    child = ET.fromstring(item)
                    root.append(child)
                ET.indent(root, space='\t', level=0, use_tabs=True)
                file.write(ET.tostring(root, encoding='unicode', method='xml'))
            elif self.output_format == 'tsv':
                writer = csv.writer(file, delimiter='\t')
                for row in data:
                    writer.writerow(row)

class ScraperCLI:
    def __init__(self):
        self.parser = argparse.ArgumentParser()

    def parse_args(self):
        self.parser.add_argument('-u', '--url', type=str, required=True, help='URL to scrape')
        self.parser.add_argument('-c', '--config', type=str, default='config.json', help='Configuration file path (default: config.json)')
        self.args = self.parser.parse_args()

    def run(self):
        with open(self.args.config) as f:
            config = json.load(f)
            scraper = Scraper(config)
            scraper.scrape(self.args.url)

if __name__ == '__main__':
    cli = ScraperCLI()
    cli.run()
