import gzip, hashlib, subprocess

def deserialize_and_validate(binary_data):
    # Deserialize the compressed binary data and obtain the raw bytes.
    data = gzip.decompress(binary_data)

    # Create an instance of HMACValidator in a separate process (C# DLL).
    hmac_validator = subprocess.run(['HMACValidator', 'init'], capture_output=True, text=True)

    # Validate each PDU in the deserialized data using the provided base64-encoded signature.
    for pdu in iter(lambda: data.read(1024), b''):
        hmac = subprocess.run(['HMACValidator', 'validate', pdu.hex(), hmac_validator.stdout], capture_output=True, text=True)
        if not hmac.returncode == 0:
            print(""Signature validation failed for PDU."")
            break

    # If all signatures were validated successfully, process the PDUs as needed.
