import random
import string
from typing import List

def is_valid_input(num_packets: int, min_id: int, max_id: int, min_source: str, max_source: str, min_dest: str):
    if not isinstance(num_packets, int) or num_packets <= 0:
        return False
    if not isinstance(min_id, int) or min_id > max_id:
        return False
    if not isinstance(max_id, int) or max_id < min_id:
        return False
    if not all([isinstance(x, str) for x in [min_source, max_source, min_dest]]):
        return False
    if len(min_source) > len(max_source) or len(min_dest) > len(max_dest):
        return False
    return True

def generate_nfa_packets(num_packets: int, min_id: int, max_id: int, min_source: str, max_source: str, min_dest: str):
    if not is_valid_input(num_packets, min_id, max_id, min_source, max_source, min_dest):
        raise ValueError(""Invalid input types or ranges provided."")

    sequence_numbers = set()
    packets = []

    for _ in range(num_packets):
        packet_id = random.randint(min_id, max_id)
        source = min_source + ''.join(random.choices(string.ascii_lowercase + string.digits, k=len(max_source) - len(min_source)))
        dest = min_dest + ''.join(random.choices(string.ascii_lowercase + string.digits, k=len(max_dest) - len(min_dest)))

        while source in packets or dest in packets:
            source = min_source + ''.join(random.choices(string.ascii_lowercase + string.digits, k=len(max_source) - len(min_source)))
            dest = min_dest + ''.join(random.choices(string.ascii_lowercase + string.digits, k=len(max_dest) - len(min_dest)))

        sequence_number = random.randint(1, 999999)
        while sequence_number in sequence_numbers:
            sequence_number = random.randint(1, 999999)

        packets.append({
            'PacketType': packet_id,
            'Source': source,
            'Destination': dest,
            'SequenceNumber': sequence_number
        })
        sequence_numbers.add(sequence_number)

    return packets
