import random
import datetime
import json
from collections import namedtuple
import threading
from concurrent.futures import ThreadPoolExecutor, ProcessPoolExecutor

class CustomerProfile:
    def __init__(self, customer_id, date_of_interaction, feedback):
        self.customer_id = customer_id
        self.date_of_interaction = datetime.datetime.strptime(date_of_interaction, ""%Y-%m-%d"")
        if not self.date_of_interaction < datetime.datetime.now():
            raise ValueError(""Date of interaction cannot be in the future."")
        self.feedback = feedback or """"

    def __repr__(self):
        return f""CustomerProfile(id={self.customer_id}, doi='{self.date_of_interaction}', feedback='{self.feedback}')""

def generate_customer_profiles(n, min_length, max_length, feedback_length=(10, 200)):
    customer_profile = namedtuple(""CustomerProfile"", ""customer_id date_of_interaction feedback"")

    def feedback_generator():
        length = random.randint(*feedback_length)
        return ''.join(random.choices(string.ascii_letters + string.digits, k=length))

    profiles = []
    customer_ids = range(1, n + 1)

    try:
        for id_ in customer_ids:
            date = datetime.datetime.now().date() + datetime.timedelta(days=random.randint(0, 365 * 2))
            profiles.append(customer_profile(*(id_, date, feedback_generator())))
    except TypeError as e:
        raise ValueError(""Number of customer profiles must be an integer."") from e

    return profiles

def save_to_file(data, filename, mode=""a""):
    import json

    with open(filename, mode) as f:
        json.dump(data, f, indent=4)

def main():
    num_profiles = int(input(""Enter the number of customer profiles to generate: ""))
    min_length = int(input(""Enter the minimum length for feedback comments: ""))
    max_length = int(input(""Enter the maximum length for feedback comments: ""))

    try:
        profiles = generate_customer_profiles(num_profiles, min_length, max_length)
        save_to_file(profiles, ""customer_profiles.json"")
    except ValueError as e:
        print(e)

    if input(""Would you like to generate more customer profiles concurrently? (y/n): "") == ""y"":
        with ThreadPoolExecutor() as executor:
            for _ in range(2):
                executor.submit(main)

if __name__ == ""__main__"":
    main()
```
