def read_integers(custom_delimiter=' ', limit=100):
    integers = []
    current_string = """"
    num_elements = 0

    while True:
        user_input = input(""Enter integers separated by "" + custom_delimiter + "" or type 'done' to finish: "")
        if user_input.lower() == 'done':
            break

        for char in user_input:
            if char.isdigit() or char == custom_delimiter:
                current_string += char
            elif num_elements >= limit:
                print(f""Error: Too many elements ({num_elements}). Please enter less than {limit} integers."")
                return []
            else:
                print(""Error: Invalid character:"", char)
                return []

        try:
            num = int(current_string)
            integers.append(num)
            num_elements += 1
            current_string = """"
        except ValueError:
            print(""Error: Invalid integer input:"", current_string)

    return integers

def sort_options(array):
    order_choice = input(""Sort the array in ascending (a) or descending (d) order? "").lower()
    if order_choice == 'a':
        return sorted(array)
    elif order_choice == 'd':
        return sorted(array, reverse=True)
    else:
        print(""Invalid choice. Sorting in ascending order."")
        return sorted(array)

def appendSlashIfWithinLimit(input_list, limit=100):
    output_string = ''
    count = 0
    for item in input_list:
        output_string += str(item)
        count += len(str(item))

        if count > limit - len(custom_delimiter):
            output_string += '/'

        if count > limit:
            break

    return output_string

custom_delimiter = input(""Enter custom delimiter (default is space): "") or ' '
integers_array = read_integers(custom_delimiter)
sorted_array = sort_options(integers_array)
output_with_slashes = appendSlashIfWithinLimit(sorted_array)
print(f""Sorted array with delimited strings: {output_with_slashes}"")
