0,"Devise a Python function tasked with parsing a text file to identify and isolate all singular email addresses, disregarding any unrelated content. This function should output a dictionary, with each distinct email address serving as a key and the corresponding count of its occurrences within the file as its value. Ensure robust error management to address situations where the file cannot be located or is devoid of content.",185,,"['```python
import re
from pathlib import Path
from typing import Dict

def parse_emails(file_path: str) -> Dict[str, int]:
    if not Path(file_path).is_file():
        return {""Error"": ""File not found.""}

    email_counts = {}
    with open(file_path) as f:
        for line in f:
            email = re.findall(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', line)
            if email:
                for e in email:
                    email_counts[e] = email_counts.get(e, 0) + 1

    return {k: v for k, v in sorted(email_counts.items(), key=lambda item: item[1], reverse=True)}
