def css_to_html_style_tags(css_styles, unique_prefix):
    html_styles = """"
    index = 1
    for style in css_styles:
        key = f""{unique_prefix}{index}""
        html_styles += f'<style>{key} {{ {style} }}</style>\n'
        index += 1
    return html_styles.strip()
