import csv
import openpyxl
import sys

def convert_csv_to_excel(csv_file, excel_file):
    try:
        with open(csv_file, 'r') as csvfile:
            data = list(csv.reader(csvfile))

        wb = openpyxl.Workbook()
        ws = wb.active

        for row in data:
            ws.append(row)

        wb.save(excel_file)

        return 0
    except Exception as e:
        print(f""Error: {e}"")
        return 1

def main():
    if len(sys.argv) != 3:
        print(""Usage: script.py <input_csv> <output_excel>"")
    else:
        csv_file, excel_file = sys.argv[1], sys.argv[2]

        status_code = convert_csv_to_excel(csv_file, excel_file)

if __name__ == ""__main__"":
