import json
import base64
from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.asymmetric import hmac, sha256
from cryptography.hazmat.serialization import Encoding

def generate_key_iv():
    key = get_random_bytes(32)
    iv = get_random_bytes(12)
    return key, iv

def aes_gcm_encrypt(data, key, iv):
    cipher = AES.new(key, AES.MODE_GCM, iv)
    tag = cipher.tag
    encrypted_text = cipher.encrypt(data)
    return base64.b64encode(iv + encrypted_text + tag).decode()

def create_json_objects():
    custom_objects = []
    for i in range(10):
        json_obj = {""id"": i, ""content"": {""key"": ""value""}}
        key, iv = generate_key_iv()
        encrypted_content = aes_gcm_encrypt(json.dumps(json_obj[""content""]), key, iv)
        json_obj[""content""][""ciphertext""] = encrypted_content
        json_obj[""signature""] = hmac_sha256_hmac(key, json.dumps(json_obj))
        custom_objects.append(json_obj)
    return custom_objects

def hmac_sha256_hmac(key, data):
    key = bytes(key, ""utf-8"")
    hmac_obj = hmac.new(key, data, sha256.new())
    return hmac_obj.finalize()

def serialize_to_binary(data):
    return json.dumps(data, cls=JsonCustomEncoder).encode(""utf-8"")

class JsonCustomEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, bytes):
            return base64.b64encode(obj).decode()
        return json.JSONEncoder.default(self, obj)
