**Python Script (python_script.py)**

```python
import json
import base64
from cryptography.fernet import Fernet
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.primitives.hashes import SHA256
from CryptoPlusPlus.RSA import RSAKey
from CryptoPlusPlus.AESGCM import AESGCM
import os

def generate_random_string(length):
    # Generate dynamic clinic details for testing purposes
    chars = ""abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789""
    return ''.join(random.choice(chars) for _ in range(length))

def encrypt_json(json_data, key):
    # Encrypt the JSON data using AES-GCM encryption with HMAC-SHA256 verification
    f = Fernet(key)
    json_bytes = json.dumps(json_data).encode()
    nonce = os.urandom(12)
    ciphertext, tag = f.encrypt(json_bytes, nonce, additional_authenticated_data=None, tag_length=16)
    return base64.urlsafe_b64encode(nonce + ciphertext + tag).decode()

def deserialize_binary_data(serialized_binary_data):
    # Deserialize the binary data back into JSON objects
    key = RSAKey.generate(2048, default_backend())
    AESGCM.set_rsa_key(key)
    binary_data = base64.urlsafe_b64decode(serialized_binary_data)
    nonce, ciphertext, tag = bytes(binary_data[:12]), bytes(binary_data[12:]), bytes(binary_data[-16:])
    json_bytes = AESGCM.decrypt(ciphertext, nonce, tag)
    return json.loads(json_bytes)

