```python
import os
import hashlib
from tqdm import tqdm

def compute_file_hash(file_path, hash_algorithm='sha256', block_size=4096):
    if not os.path.exists(file_path):
        raise FileNotFoundError(f""File {file_path} not found."")

    if not callable(hashlib.new(hash_algorithm)):
        raise ValueError(f""Unsupported hash algorithm: {hash_algorithm}."")

    hasher = hashlib.new(hash_algorithm)

    try:
        with open(file_path, 'rb') as f:
            for chunk in tqdm(iter(lambda: f.read(block_size), b''), total=os.path.getsize(file_path), unit='B', unit_scale=True):
                hasher.update(chunk)
    except IOError as e:
        raise IOError(f""Error reading file: {e}"")

    return hasher.hexdigest()

def compute_directory_hash(directory_path, hash_algorithm='sha256', block_size=4096, include_extensions=None):
    if not os.path.exists(directory_path):
        raise FileNotFoundError(f""Directory {directory_path} not found."")

    hashes = {}

    def add_file_to_hashes(filename):
        file_fullpath = os.path.join(directory_path, filename)
        if os.path.isfile(file_fullpath) and (not include_extensions or filename.lower().endswith(include_extensions)):
            hashes[filename] = compute_file_hash(file_fullpath, hash_algorithm, block_size)

    try:
        for root, dirs, files in os.walk(directory_path):
            for filename in files:
                add_file_to_hashes(filename)

    except Exception as e:
        print(f""Error computing directory hash: {e}"")

    return hashes

def store_hashes(hashes_dict, output_filename=""hashes.txt""):
    with open(output_filename, 'w') as output_file:
        for file_name, file_hash in hashes_dict.items():
            output_file.write(f""{file_name}: {file_hash}\n"")
```

