import ctypes
import json

class JsonEncryptPy(ctypes.CDLL):
    def __init__(self, dll_name='json_encrypt.dll'):
        super().__init__(dll_name)

    def encrypt(self, json_str):
        json_obj = json.loads(json_str)
        return self.c_encrypt(ctypes.c_char_p(json.dumps(json_obj).encode('utf-8'))).decode('utf-8')

    def decrypt(self, encrypted_json):
        json_obj = json.loads(ctypes.cast(self.c_decrypt(encrypted_json.encode('utf-8')), ctypes.c_char_p).decode('utf-8'))
        return json.dumps(json_obj)
