import os
import sys

def create_venv(project_name, project_path):
    if not os.path.exists(project_path):
        print(""Error: Project directory does not exist."")
        return

    venv_dir = os.path.join(project_path, '.venv')
    if os.path.exists(venv_dir):
        print(""Warning: Virtual environment already exists. Use 'deactivate' or delete .venv folder to recreate."")
    else:
        venv_path = os.path.join(venv_dir, 'venv')
        try:
            cmd = f""{sys.executable} -m venv {venv_path}""
            os.system(cmd)
            print(""Virtual environment created successfully."")
        except Exception as e:
            print(f""Error creating virtual environment: {e}"")

if __name__ == ""__main__"":
    if len(sys.argv) < 3:
        print(""Usage: python create_venv.py [project_name] [project_path]"")
        sys.exit(1)

    project_name = sys.argv[1]
    project_path = sys.argv[2]

    create_venv(project_name, project_path)
