0,"Create a Python program that implements a library management system. The system should allow users to add new books with their titles, authors, and publication years, update book details, and generate a catalog that lists all books along with their average user ratings based on the last 5 reviews. Incorporate error handling for scenarios where a book is not found or when the library exceeds a predefined maximum capacity.",680,,"['```python
import collections

MAX_CAPACITY = 100

class Library:
    def __init__(self):
        self.books = []

    def add_book(self, title, author, year, rating=None):
        if len(self.books) >= MAX_CAPACITY:
            raise ValueError(""Library is full."")
        book = {""title"": title, ""author"": author, ""year"": year, ""ratings"": []}
        self.books.append(book)
        if rating:
            book[""ratings""].append(rating)

    def update_book(self, title, field, value):
        for b in self.books:
            if b[""title""] == title:
                if field == ""author"":
                    b[""author""] = value
                elif field == ""year"":
                    b[""year""] = value
                elif field == ""rating"" and len(b[""ratings""]) < 5:
                    b[""ratings""].append(value)
                    break
        else:
            raise KeyError(""Book not found."")

    def average_rating(self, title):
        for book in self.books:
            if book[""title""] == title:
                return sum(book[""ratings""]) / len(book[""ratings""])
        raise KeyError(""Book not found."")

    def catalog(self):
        for b in sorted(self.books, key=lambda x: (x[""year""], x[""title""])):
            avg_rating = self.average_rating(b[""title""]) if len(b[""ratings""]) >= 5 else ""No ratings yet""
            print(f""{b['title']} by {b['author']} ({b['year']}), Average Rating: {avg_rating}"")

# Usage example
library = Library()
library.add_book(""The Catcher in the Rye"", ""J.D. Salinger"", 1951, 4.8)
library.add_book(""To Kill a Mockingbird"", ""Harper Lee"", 1960)
library.update_book(""The Catcher in the Rye"", ""rating"", 4.9)
