       if ""@"" not in email:
           return False
       # Ensure ""@"" is not at the beginning or end of the string
       if email.startswith(""@"") or email.endswith(""@""):
           return False
       # Check for at least one ""."" after ""@""
       at_index = email.find(""@"")
       dot_after_at = ""."" in email[at_index + 1:]
       if not dot_after_at:
           return False
       # Ensure at least one character between ""@"" and first "".""
       if len(email) - (at_index + 1) < 1:
           return False
       # Validate domain name length (2-6 characters)
       domain_start = email.rfind(""."", at_index)
       if domain_start == -1 or domain_start <= at_index:
           return False
       domain_length = len(email) - domain_start - 1
       if not (2 <= domain_length <= 6):
           return False
       # Validate local part includes allowed characters and no consecutive dots
       allowed_chars = set(""abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-"")
       for char in email[:domain_start]:
           if char not in allowed_chars:
               return False

       local_part_end = at_index
       for char in email[local_part_end + 1:domain_start]:
           if char in {""."", ""..""}:
