import datetime
import random

class TemperatureSensorData:
    def __init__(self, timestamp, temp, id):
        self.timestamp = timestamp
        self.temperature = temp
        self.id = id

def generate_sensor_data(num_sensors, num_entries):
    sensors = {}
    for i in range(1, num_sensors + 1):
        sensors[i] = []

    for _ in range(num_entries):
        timestamp = datetime.datetime.now()
        temp = round(random.uniform(-50, 200), 2)
        sensor_id = random.randint(1, num_sensors)
        sensors[sensor_id].append(TemperatureSensorData(timestamp, temp, sensor_id))

    return [sensors[i] for i in range(1, num_sensors + 1)]
