import re

def analyze_text(texts):
    result = {}
    for text in texts:
        words = text.split()
        word_count = len(words)
        avg_word_length = sum(len(word) for word in words) / word_count if word_count else 0
        punctuation = sum([c in "".!?"" for c in text] if re.search('[a-zA-Z]', text) else 0)/len(text) if text else 0
        all_uppercase = len(text) == len(text.upper())
        word_frequencies = {word: words.count(word) for word in set(words)}
        result[text] = {""word_count"": word_count, ""avg_word_length"": avg_word_length, ""punctuation_percentage"": punctuation, ""all_uppercase"": all_uppercase, ""word_frequencies"": word_frequencies}
    return result
