import random
from typing import List

class EmployeeProfile:
    def __init__(self, name, age, occupation, salary, department, location):
        self.name = name
        self.age = age
        self.occupation = occupation
        self.salary = salary
        self.department = department
        self.location = location

def generate_first_names(num_names=10):
    return [''.join(random.choices(string.ascii_uppercase + string.digits + string.ascii_lowercase, k=randint(5, 10))) for _ in range(num_names)]

def generate_job_titles(override=None):
    if override:
        return override
    else:
        return [""Developer"", ""Manager"", ""Designer"", ""Tester"", ""Engineer""]

def generate_departments(override=None):
    if override:
        return override
    else:
        return [""IT"", ""HR"", ""Finance"", ""Marketing"", ""Sales""]

def generate_locations(override=None):
    if override:
        return override
    else:
        return [""New York"", ""San Francisco"", ""Seattle"", ""Los Angeles"", ""Chicago""]

def generate_employee_profiles(num_profiles=10,
                                first_names=None,
                                job_titles=None,
                                departments=None,
                                locations=None):
    if not first_names:
        first_names = generate_first_names()
    if not job_titles:
        job_titles = generate_job_titles()
    if not departments:
        departments = generate_departments()
    if not locations:
        locations = generate_locations()

    profiles = []
    for _ in range(num_profiles):
        name = first_names.pop(random.randint(0, len(first_names) - 1))
        age = random.randint(18, 65)
        occupation = job_titles[random.randint(0, len(job_titles) - 1)]
        salary = random.uniform(30000, 150000)
        department = departments[random.randint(0, len(departments) - 1)]
        location = locations[random.randint(0, len(locations) - 1)]

        employee_profile = EmployeeProfile(name, age, occupation, salary, department, location)
        profiles.append(employee_profile)
    return profiles
