0,"Create a Python class named ""FileSizeEstimator"" that estimates the size of files in a given directory, taking into account the sizes of all subdirectories and files within. This class should provide methods for initializing with a directory path, estimating the total size, and retrieving the estimated size as well as details about individual files and their sizes. It should also include a method to display these details in an easily readable format. The purpose of this class is to help developers and system administrators efficiently manage storage space by providing an accurate estimation of the total file sizes in specific directories, which can be particularly useful for monitoring disk usage or planning backups.",862,,"['```python
import os
from collections import OrderedDict

class FileSizeEstimator:
    def __init__(self, directory_path):
        self.directory_path = directory_path
        self.size_dict = self._get_file_sizes()

    def _get_file_sizes(self):
        file_sizes = OrderedDict()
        for root, dirs, files in os.walk(self.directory_path):
            for file in files:
                file_path = os.path.join(root, file)
                file_size = os.stat(file_path).st_size
                file_sizes[file] = file_size
        return file_sizes

    def total_size(self):
        return sum(self.size_dict.values())

    def details(self):
        detail_format = ""{:<20}{:<15}""
        print(""\nFile Size Estimator Details:\n"")
        for file, size in self.size_dict.items():
            print(detail_format.format(file, str(size) + "" bytes""))

    def display_stats(self):
        total_size = self.total_size()
        details = ""Total Size: {:,} bytes"".format(total_size)
        print(""\nFile Size Estimator Stats:\n"")
        print(details)
