import os
import zipfile
import hashlib
import base64

def compress_and_md5(src, dest):
    # Your compression logic here...
    md5 = hashlib.md5()
    with open(src, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""""):
            md5.update(chunk)
    return dest + '.zip', base64.b64encode(md5.digest()).decode()

def decompress_and_verify_md5(src, dest):
    # Your compression logic here...
    if src.endswith('.zip'):
        with zipfile.ZipFile(src, 'r') as zf:
            for member in zf.namelist():
                zf.extract(member, dest)
    return dest
