0,"Create a class named `FileProcessor` that encapsulates the ability to read and process a text file. The class should include methods for opening the file, reading its content, splitting the text into sentences, and calculating the average length of these sentences. Additionally, implement a feature to save processed data, such as sentence lengths or frequency of specific words, into another file. Ensure proper memory management and handle potential exceptions during file operations.",680,,"['```python
import re
from typing import List, Dict
import sys
import os

class FileProcessor:
    def __init__(self, file_path: str):
        self.file_path = file_path

    def open_file(self) -> None:
        try:
            with open(self.file_path, 'r', encoding='utf-8') as f:
                pass
        except FileNotFoundError:
            print(f""File not found: {self.file_path}"")
            sys.exit(1)

    def read_content(self) -> str:
        content = """"
        self.open_file()
        with open(self.file_path, 'r', encoding='utf-8') as f:
            content = f.read()
        return content

    def split_into_sentences(self, text: str) -> List[str]:
        sentences = re.split(r'[.!?]\s+', text)
        return [sentence.strip() for sentence in sentences if sentence]

    def calculate_avg_sentence_length(self, sentences: List[str]) -> float:
        avg_len = sum([len(sentence.split()) for sentence in sentences]) / len(sentences)
        return round(avg_len, 2)

    def save_processed_data(self, data: Dict, output_file: str) -> None:
        try:
            with open(output_file, 'w', encoding='utf-8') as f:
                for key, value in data.items():
                    f.write(f""{key}: {value}\n"")
        except Exception as e:
            print(f""Error saving processed data to file: {e}"")

    def process_file(self) -> None:
        content = self.read_content()
        sentences = self.split_into_sentences(content)
        sentence_lengths = [len(sentence.split()) for sentence in sentences]
        avg_sentence_length = self.calculate_avg_sentence_length(sentences)

        processed_data = {
            ""average_sentence_length"": avg_sentence_length,
            ""sentence_lengths"": sentence_lengths
        }

        self.save_processed_data(processed_data, 'processed_data.txt')
