    return data // Return the processed data
}

func fetchFont(url: URL, cacheSize limit: Int = 10) {
    let fontCache = LRUCache<URL>(maxCapacity: limit)
    if let fontData = downloadFont(url, cache: &fontCache) {
        let compressedFontData = parseAndCompressFontData(fontData)
