def create_nfa(num_states):
    nfa = defaultdict(lambda: set())
    for _ in range(num_states + 1):
        nfa[str(i)] = {}
    return nfa

def set_transition(nfa, current_state, input_char, next_state):
    if current_state not in nfa or input_char not in nfa[current_state]:
        nfa[current_state][input_char] = set()
    nfa[current_state][input_char].add(next_state)

def mark_as_final(nfa, final_states=None):
    if final_states is None:
        for state in nfa:
            if state[-1] == 'q':
                nfa[state]['F'] = True
    else:
        for state in final_states:
            nfa[state]['F'] = True

parser = argparse.ArgumentParser(description='Configure an NFA.')
parser.add_argument('--num-states', type=int, help=""Number of states (required)"")
parser.add_argument('--states', '--s', nargs='+', type=json.loads, help=""States configuration (comma-separated or --states json file)"")
parser.add_argument('--final-states', '--fs', nargs='+', type=json.loads, help=""Final states configuration (comma-separated or --final-states json file)"")
parser.add_argument('--config', '-c', default='config.json', help=""Path to the JSON configuration file (default: config.json)"")

args = parser.parse_args()

config_params = load_config(args.config)
if config_params is not None:
    num_states, states, final_states = config_params
else:
    num_states = args.num_states
    states = args.states
    final_states = args.final_states

nfa = create_nfa(num_states)
if states is not None:
