         total_size = sum([row[1] for row in report_rows])

        file_type_sizes = {
            'files': sum([row[1] for row in report_rows if row[0].endswith(('\\', '/')), 0], 0),
            'directories': total_size - file_type_sizes['files']
        }

        percentage_breakdown = {
            'total': total_size,
            'files': file_type_sizes['files'] / total_size * 100,
            'directories': file_type_sizes['directories'] / total_size * 100
        }

        custom_output.append(f'Total Storage Usage: {total_size} bytes')
        custom_output.append(f'File Type Breakdown (%): Files - {percentage_breakdown[""files""]:.2f}, Directories - {percentage_breakdown[""directories""]:.2f}')
        return custom_output
