This crossover effectively merges Java's cryptographic capabilities with Python's ease of use and IoT-specific data handling, ensuring that each device registration request is not only uniquely identifiable",680,,"[' ```python
import time
import hashlib
import base64

def generate_iot_registration_request(device_id, ip_address, algorithm='md5', encode_base64=False):
    current_timestamp = int(time.time())
    payload = f""{device_id},{ip_address},{current_timestamp}""

    if algorithm.lower() in ['sha1', 'sha-1']:
        hashed_payload = hashlib.sha1(payload.encode()).digest()
    else:
        hashed_payload = hashlib.md5(payload.encode()).digest()

    if encode_base64:
        hashed_payload = base64.b64encode(hashed_payload).decode()

    if encode_base64 and algorithm.lower() == 'sha1':
        return hashed_payload.hex()

    return {
        ""device_id"": device_id,
        ""ip_address"": ip_address,
        ""timestamp"": current_timestamp,
    }

# Example usage:
registration_request = generate_iot_registration_request(
    ""A0B0C0D0E0F0"",
    ""192.168.1.2"",
    algorithm='sha-1',
    encode_base64=True,
)
print(registration_request)
```
