        sort_key_func = lambda x: x.split(custom_delimiter)[0]

        custom_order_inputs = input(""Enter custom sorting criteria separated by commas (default is index): "").split(',')

        if len(custom_order_inputs) > 2 or len(custom_order_inputs) < 1:
            print(""Invalid number of criteria. Using default sorting criteria."")

        sort_key_func_map = {'index': lambda x: int(x.split(custom_delimiter)[0]),
                             'value': lambda x: int(x)}

        key_func_used, *order_directions_list = [x.strip() for x in custom_order_inputs]

        sort_key_func_to_use = sort_key_func_map.get(key_func_used, None)

        if not sort_key_func_to_use:
            print(f""Invalid key function '{key_func_used}'. Defaulting to value."")

